UPDATE companies SET description='Carbone Metal Fabricator Inc. operates from a 44,000-square-foot facility in Chelsea, Massachusetts. The company was founded in 1966 and has built a reputation over six decades for custom-fabricated stainless-steel and metal products.

The shop provides a full suite of in-house services including fabrication, engineering, project management, design and prototyping, and support services with installation coordination. Its equipment roster includes state-of-the-art manufacturing technology for precision work, producing items ranging from foodservice equipment and healthcare laboratory apparatus to residential architectural features such as stair railings and kitchen hoods, as well as decorative metal pieces for commercial and residential spaces.

Carbone serves the foodservice, healthcare, residential, and decorative metals sectors. Notable projects include the Corning Museum of Glass, the Dean & DeLuca STAGE and the Alexan Wrentham Apartments. The company works closely with architects, interior designers, contractors, and research institutions to deliver custom metalwork.

The firm emphasizes a “first-pass” quality standard, assigning a dedicated team of tenured engineers and project managers to each job. Its quality-control procedures are designed to meet or exceed national safety standards, and the company describes its output as jewelry-quality craftsmanship built to withstand rigorous commercial use.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Fabrication (custom stainless steel and metal)", "Engineering", "Project Management", "Design & Prototyping", "Support Services", "Installation Coordination", "Foodservice Equipment Fabrication", "Healthcare Laboratory Equipment Fabrication", "Residential Architectural Metalwork", "Decorative Metal Fabrication"], "industries": ["Foodservice", "Healthcare", "Residential", "Decorative Metals", "Commercial", "Institutional"], "materials": ["Stainless Steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["First-pass quality: dependable, timely, and pristine product delivery", "44,000 sq ft facility with state-of-the-art specialized equipment", "Dedicated project teams including tenured engineers and project managers", "Products meet or exceed national safety standards", "Jewelry-quality craftsmanship with strict quality control"], "facts_used": ["Founded in 1966 -> db", "Headquartered in Chelsea, Massachusetts -> db", "44,000 sq ft facility -> /about-us", "Custom fabrication of stainless steel and metal products -> /", "Services: Fabrication, Engineering, Project Management, Design & Prototyping, Support Services -> /services", "Industries served: Foodservice, Healthcare, Residential, Decorative Metals -> /", "Projects: Corning Museum of Glass, Dean & DeLuca STAGE, 50 Liberty Drive, Alexan Wrentham Apartments -> / and db", "Dedicated team per project with tenured engineers and project managers -> /about-us", "Products meet or exceed national safety standards -> /about-us", "Jewelry-quality craftsmanship with strict quality control -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Carbone Metal Fabricator brings passion and expertise to the creation of the most visually stunning, custom-fabricated stainless-steel and metal products.", "founded_year": "1966", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='carbone-metal-fabricator-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Carnegie Fabrics was founded in 1950 in New York, New York. The company has operated as a manufacturer of interior textiles, wallcoverings, and acoustic solutions for over 70 years.

Carnegie produces proprietary Xorel® brand textiles, including Biobased Xorel®—the world’s first plant-based, high-performance textile made from 85% rapidly renewable sugarcane. The product portfolio spans PVC-free upholstery, wallcoverings, and fully customizable acoustic solutions such as Xorel Artform and Kirei. The company also provides complimentary design services, including curated sample packages, layout renderings, and budget projections for acoustic installations.

Its materials have been specified in projects requiring high-performance, sustainable interiors, and the firm partners with organizations such as Creation Baumann and WOOD-SKIN to expand its material offerings.

Carnegie differentiates itself as the first and only 100% PVC-free interior textile and wallcovering company, a commitment it describes as a “forever promise.” It has maintained B Corp certification since 2014, provides Health Product Declarations for every product, and achieved Living Product Challenge Certification for Biobased Xorel—industry-first credentials that underscore its focus on material transparency and environmental responsibility.', certifications=ARRAY['B Corp','Living Product Challenge']::text[], profile='{"capabilities": ["Textile manufacturing (Xorel, Biobased Xorel)", "Wallcovering manufacturing", "Acoustic solutions manufacturing (Xorel Artform, Kirei)", "Design services: curated sample packages, layout renderings, budget projections", "Xorel Artform design and layout services", "Acoustic solution design services"], "industries": ["Commercial interior design", "Architecture", "Healthcare", "Hospitality", "Education", "Corporate workplace"], "materials": ["Biobased Xorel (85% biobased from sugarcane)", "Xorel (proprietary high-performance textile)", "PVC-free textiles and wallcoverings"], "equipment": [], "volume": "", "lead_time": "Overnight samples; same-day design solutions", "tolerances": "", "built_on": ["First and only 100% PVC-free interior textile and wallcovering company", "Biobased Xorel: first textile to achieve Living Product Challenge Certification", "B Corp certified since 2014", "Health Product Declarations provided for every product", "Complimentary design services including same-day sample curation and overnight delivery"], "facts_used": ["Founded 1950 in New York, NY -> /about-us", "B Corp certified since 2014 -> /, /about-us", "First and only PVC-free interior textile and wallcovering company -> /, /about-us", "Biobased Xorel first textile to achieve Living Product Challenge Certification -> /, /about-us", "Proprietary Xorel brand textiles -> /about-us", "Complimentary design services (curated samples, acoustic layout, Xorel Ar